/**
 * Review reproducers for the develop merge: fixed LMDB reader pool vs. planner-time nested reads, and sampled planning
 * cardinalities.
 */
public class LmdbMergeIntegrationReviewReproTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "http://ex/";

	private static TripleStore tripleStore(LmdbStore store) throws Exception {
		Field field = LmdbSailStore.class.getDeclaredField("tripleStore");
		field.setAccessible(true);
		return (TripleStore) field.get(store.getBackingStore());
	}

	private static ValueStore valueStore(LmdbStore store) throws Exception {
		Field field = LmdbSailStore.class.getDeclaredField("valueStore");
		field.setAccessible(true);
		return (ValueStore) field.get(store.getBackingStore());
	}

	private static SailRepository repository(Path dir) {
		LmdbStore store = new LmdbStore(dir.toFile(), new LmdbStoreConfig());
		SailRepository repository = new SailRepository(store);
		repository.init();
		return repository;
	}

	private static void loadSelfLoops(SailRepository repository) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			IRI p = VF.createIRI(NS, "p");
			for (int i = 0; i < 200; i++) {
				IRI s = VF.createIRI(NS, "s" + i);
				conn.add(s, p, i % 2 == 0 ? s : VF.createIRI(NS, "o" + i));
				conn.add(s, VF.createIRI(NS, "q"), VF.createLiteral(i));
			}
			conn.commit();
		}
	}

	private static List<TxnManager.Txn> hold(TxnManager manager, int count) throws Exception {
		List<TxnManager.Txn> held = new ArrayList<>();
		for (int i = 0; i < count; i++) {
			held.add(manager.createReadTxn());
		}
		return held;
	}

	private static void release(List<TxnManager.Txn> held) {
		for (TxnManager.Txn txn : held) {
			txn.close();
		}
		held.clear();
	}

	/**
	 * All ordinary slots are taken (126 other queries + this query's dataset). develop's nested planner estimate
	 * (doWithPriority) proceeds; the branch's repeated-variable estimate (ordinary createReadTxn) stalls for 30 s.
	 */
	@Test
	public void nestedOrdinaryPlannerReadStallsWherePriorityReadProceeds(@TempDir Path dir) throws Exception {
		SailRepository repository = repository(dir);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		List<TxnManager.Txn> held = new ArrayList<>();
		try {
			loadSelfLoops(repository);
			LmdbStore store = (LmdbStore) repository.getSail();
			TripleStore tripleStore = tripleStore(store);
			long p = valueStore(store).getId(VF.createIRI(NS, "p"));
			held.addAll(hold(tripleStore.getTxnManager(), TxnManager.POOL_SIZE - 1));
			int mask = TripleStore.repeatedComponentPairMask(TripleStore.SUBJ_IDX, TripleStore.OBJ_IDX);

			Future<Double> priority = executor.submit(() -> tripleStore.cardinality(-1, p, -1, -1));
			Future<Double> ordinary = executor
					.submit(() -> tripleStore.repeatedVariableCardinality(-1, p, -1, -1, mask));

			long start = System.nanoTime();
			double priorityRows = priority.get(5, TimeUnit.SECONDS);
			System.out.println("priority nested estimate returned " + priorityRows + " after "
					+ TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start) + " ms");
			boolean ordinaryDone;
			try {
				ordinary.get(5, TimeUnit.SECONDS);
				ordinaryDone = true;
			} catch (java.util.concurrent.TimeoutException e) {
				ordinaryDone = false;
			}
			assertTrue(ordinaryDone,
					"repeatedVariableCardinality (ordinary reader) is still blocked after 5 s while the priority "
							+ "estimate completed; it only fails after the 30 s admission timeout");
		} finally {
			release(held);
			executor.shutdownNow();
			executor.awaitTermination(40, TimeUnit.SECONDS);
			repository.shutDown();
		}
	}

	/**
	 * End-to-end: only one ordinary slot left (taken by the query's own dataset). Planning a repeated-variable query
	 * needs a nested ordinary read.
	 */
	@Test
	public void repeatedVarQueryWithOnlyDatasetSlotsFree(@TempDir Path dir) throws Exception {
		runQueryWithFreeOrdinarySlots(dir, "SELECT (COUNT(*) AS ?c) WHERE { ?s <http://ex/p> ?s }", 2);
	}

	@Test
	public void controlPlainQueryWithOnlyDatasetSlotsFree(@TempDir Path dir) throws Exception {
		runQueryWithFreeOrdinarySlots(dir, "SELECT (COUNT(*) AS ?c) WHERE { ?s <http://ex/p> ?o }", 2);
	}

	@Test
	public void filterQueryPlanningStallsWithOnlyDatasetSlotsFree(@TempDir Path dir) throws Exception {
		runQueryWithFreeOrdinarySlots(dir,
				"SELECT (COUNT(*) AS ?c) WHERE { ?s <http://ex/p> ?o . ?s <http://ex/q> ?n FILTER(?n > 150) }", 2);
	}

	private void runQueryWithFreeOrdinarySlots(Path dir, String query, int freeSlots) throws Exception {
		SailRepository repository = repository(dir);
		List<TxnManager.Txn> held = new ArrayList<>();
		AtomicReference<Throwable> failure = new AtomicReference<>();
		AtomicReference<String> result = new AtomicReference<>();
		Thread worker = null;
		try {
			loadSelfLoops(repository);
			// warm-up run without pressure (prints nothing, but initialises lazy structures)
			try (SailRepositoryConnection conn = repository.getConnection();
					TupleQueryResult res = conn.prepareTupleQuery(query).evaluate()) {
				while (res.hasNext()) {
					res.next();
				}
			}
			LmdbStore store = (LmdbStore) repository.getSail();
			held.addAll(hold(tripleStore(store).getTxnManager(), TxnManager.POOL_SIZE - 1 - freeSlots));
			worker = new Thread(() -> {
				try (SailRepositoryConnection conn = repository.getConnection();
						TupleQueryResult res = conn.prepareTupleQuery(query.replace("COUNT(*)", "COUNT(?s)"))
								.evaluate()) {
					StringBuilder sb = new StringBuilder();
					for (BindingSet bs : res) {
						sb.append(bs);
					}
					result.set(sb.toString());
				} catch (Throwable t) {
					failure.set(t);
				}
			}, "review-query");
			long start = System.nanoTime();
			worker.start();
			worker.join(8_000);
			boolean done = !worker.isAlive();
			if (!done) {
				StringBuilder stack = new StringBuilder();
				for (StackTraceElement element : worker.getStackTrace()) {
					stack.append("\n\tat ").append(element);
				}
				System.out.println("query thread blocked after 8 s:" + stack);
			} else {
				System.out.println("query finished in " + TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - start)
						+ " ms result=" + result.get() + " failure=" + failure.get());
			}
			assertTrue(done, "query did not finish within 8 s while " + freeSlots
					+ " ordinary reader slot(s) were free (see stack trace in output)");
		} finally {
			release(held);
			if (worker != null) {
				worker.join(60_000);
			}
			repository.shutDown();
		}
	}

	/**
	 * planningCardinality now delegates to the sampled page estimator. A zero for a non-empty pattern must never be
	 * produced if callers label it DATABASE_EXACT (finite lookup probes).
	 */
	@Test
	public void planningCardinalityOnSkewedData(@TempDir Path dir) throws Exception {
		SailRepository repository = repository(dir);
		try {
			IRI big = VF.createIRI(NS, "big");
			IRI tiny = VF.createIRI(NS, "tiny");
			IRI r = VF.createIRI(NS, "r");
			IRI hub = VF.createIRI(NS, "hub");
			IRI target = VF.createIRI(NS, "target");
			try (SailRepositoryConnection conn = repository.getConnection()) {
				conn.begin();
				for (int i = 0; i < 50_000; i++) {
					conn.add(hub, big, VF.createIRI(NS, "ho" + i));
					conn.add(VF.createIRI(NS, "s" + i), big, VF.createIRI(NS, "o" + i));
					conn.add(VF.createIRI(NS, "s" + i), r, VF.createIRI(NS, "ro" + i));
				}
				conn.add(VF.createIRI(NS, "s25000"), r, target);
				conn.add(VF.createIRI(NS, "t"), tiny, VF.createIRI(NS, "tv"));
				conn.commit();
			}
			LmdbStore store = (LmdbStore) repository.getSail();
			TripleStore ts = tripleStore(store);
			ValueStore vs = valueStore(store);
			long bigId = vs.getId(big);
			long tinyId = vs.getId(tiny);
			long rId = vs.getId(r);
			long hubId = vs.getId(hub);
			long targetId = vs.getId(target);
			long s7 = vs.getId(VF.createIRI(NS, "s7"));
			long o7 = vs.getId(VF.createIRI(NS, "o7"));
			long ho7 = vs.getId(VF.createIRI(NS, "ho7"));
			long[][] patterns = {
					{ -1, bigId, -1, -1 },
					{ hubId, bigId, -1, -1 },
					{ s7, bigId, -1, -1 },
					{ -1, tinyId, -1, -1 },
					{ -1, -1, targetId, -1 },
					{ -1, rId, targetId, -1 },
					{ -1, bigId, o7, -1 },
					{ -1, -1, ho7, -1 },
					{ s7, -1, -1, -1 },
					{ hubId, -1, -1, -1 },
					{ -1, -1, -1, -1 } };
			List<String> zeroForNonEmpty = new ArrayList<>();
			for (long[] pattern : patterns) {
				double planning = ts.planningCardinality(pattern[0], pattern[1], pattern[2], pattern[3]);
				double exact = ts.exactCardinality(pattern[0], pattern[1], pattern[2], pattern[3]);
				String label = java.util.Arrays.toString(pattern);
				System.out.println("pattern " + label + " planning=" + planning + " exact=" + exact + " ratio="
						+ (exact == 0 ? Double.NaN : planning / exact));
				if (exact > 0 && planning <= 0) {
					zeroForNonEmpty.add(label + " planning=" + planning + " exact=" + exact);
				}
			}
			assertTrue(zeroForNonEmpty.isEmpty(), "sampled planning cardinality returned 0 for non-empty patterns: "
					+ zeroForNonEmpty);
		} finally {
			repository.shutDown();
		}
	}
}
